"""1.0.1.dev4 test fixture (NOT runtime): 1.0.1.dev3's `estimator._grid` outputs on synthetic cohorts, so that
tests/test_jax2_dt_rule_scope.py can check dev4's scoped DT_RULE against dev3's grids BIT FOR BIT without git.

What it stores (dev3_grids.json): for each synthetic cohort (ages / events / delta stored verbatim, so the test needs
no RNG), dev3's `_grid(t, e, delta, floor_early=True, n_rule=True, early_all=True, dt_rule=X)` for X = False and
X = True -- the 1.0.1 class constants of every name (J's view: the data as given) -- as (L, solver kw, ceiling,
dt_floor). JSON floats round-trip exactly (repr), so equality in the test is bit equality.

The cohorts span the scope's boundary: KM CV well below 0.05 (the scoped rule caps dt), just below and just above
0.05, 0.05-0.16 (the UNSCOPED dev3 rule caps dt there, the scoped one must not), and above 0.16 (neither caps); one
floor-bound grid (delta/L < 9e-4), one exact-time cohort (no delta), one censored.
WINDOWED (key "windowed", added after review; the 9 cohorts above are regenerated byte for byte): 3 left-truncated
cohorts with an off-grid window (lo, hi), so that the H view's prepare SNAPS it (lo -> ceil, hi -> floor to the delta
grid, deaths in hi_eff's bin censored, censored ages above hi_eff moved down): per VIEW (J = window off, H = window on;
prepare = dev3's observation_model, `git show 787bbd1`, relabel on) the prepared (ages, events) and dev3's `_grid` on
them for dt_rule False / True -- one H view in scope, one out of scope where dev3's unscoped rule would cap, and
one whose two views straddle 0.05 (J out, H in: the scope follows each view's own prepared data).

dev3's estimator is read from git (`git show 787bbd1:methods/mle_profile_jax2/estimator.py`, sha256 checked against
1.0.1.dev3's VERSION_LOCK entry), never from the working tree.
usage: PYTHONPATH=<SRtools_kappa>:<repo> python make_dev3_grids.py   (writes dev3_grids.json next to this file)
"""
from __future__ import annotations

import hashlib
import importlib.util
import json
import os
import subprocess
import sys
import tempfile

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.abspath(os.path.join(HERE, "..", "..", "..", "..", ".."))
DEV3_COMMIT = "787bbd1c6e3bf8fefdef0a0dc090c0d6a22449c7"
DEV3_EST_SHA256 = "dad4d050f8ec5bc7ad0d4d47f978f5caad3c9f57272ec1ebb161ce3f10b676b8"
GRID_KW = dict(floor_early=True, n_rule=True, early_all=True)

#: (tag, n, target CV, delta, censor_at (None = no censoring), seed). Ages ~ Gamma(1/CV^2, scale 100 CV^2) (mean 100),
#: rounded UP to the delta grid (delta None: rounded to 1e-6 so the JSON stays short).
SPECS = [
    ("sharp_cv0.012", 1500, 0.012, 1.0, None, 11),
    ("sharp_cv0.025_censored", 2000, 0.025, 1.0, 101.0, 12),
    ("sharp_cv0.016_floor", 800, 0.015, 0.05, None, 13),
    ("sharp_cv0.035_exact", 600, 0.035, None, None, 14),
    ("just_below_0.05", 3000, 0.0495, 1.0, None, 32),
    ("just_above_0.05", 3000, 0.0495, 1.0, None, 18),
    ("mid_cv0.08", 1000, 0.08, 1.0, None, 17),
    ("mid_cv0.12_exact", 500, 0.12, None, None, 18),
    ("broad_cv0.25", 400, 0.25, 1.0, None, 19),
]
#: (tag, n drawn before truncation, target CV, delta, window (lo, hi), seed): ages ~ Gamma (mean 100), rounded UP to the
#: delta grid; only ages >= lo are kept (left truncation); ages above hi are recorded as censored AT hi (off-grid).
WINDOWED = [
    ("win_sharp_cv0.03", 2500, 0.03, 1.0, (95.5, 104.5), 21),
    ("win_mid_cv0.07", 2500, 0.07, 1.0, (90.5, 108.5), 22),
    ("win_straddle", 2500, 0.065, 1.0, (90.5, 108.5), 23),        # J view CV 0.0507 (out), H view 0.0496 (IN)
]


def dev3_estimator():
    src = subprocess.run(["git", "-C", ROOT, "show", f"{DEV3_COMMIT}:methods/mle_profile_jax2/estimator.py"],
                         capture_output=True, check=True).stdout
    if hashlib.sha256(src).hexdigest() != DEV3_EST_SHA256:
        raise SystemExit("REFUSING: git's 787bbd1 estimator.py is not 1.0.1.dev3's (sha256 differs)")
    d = tempfile.mkdtemp(prefix="dev3_est_")
    p = os.path.join(d, "estimator.py")
    with open(p, "wb") as fh:
        fh.write(src)
    spec = importlib.util.spec_from_file_location("dev3_fixture.estimator", p)
    m = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = m
    spec.loader.exec_module(m)
    return m


def dev3_module(fname, key):
    src = subprocess.run(["git", "-C", ROOT, "show", f"{DEV3_COMMIT}:methods/mle_profile_jax2/{fname}"],
                         capture_output=True, check=True).stdout
    d = tempfile.mkdtemp(prefix="dev3_mod_")
    p = os.path.join(d, fname)
    with open(p, "wb") as fh:
        fh.write(src)
    spec = importlib.util.spec_from_file_location(key, p)
    m = importlib.util.module_from_spec(spec)
    sys.modules[spec.name] = m
    spec.loader.exec_module(m)
    return m, hashlib.sha256(src).hexdigest()


def windowed_cohort(n, cv, delta, window, seed):
    import numpy as np
    rng = np.random.default_rng(seed)
    k = 1.0 / cv ** 2
    t = np.round(np.ceil(rng.gamma(k, 100.0 / k, n) / delta) * delta, 6)
    lo, hi = window
    t = t[t >= lo]
    e = (t <= hi).astype(int)
    t = np.where(t > hi, hi, t)
    return [float(x) for x in t], [int(x) for x in e]


def cohort(n, cv, delta, censor_at, seed):
    import numpy as np
    rng = np.random.default_rng(seed)
    k = 1.0 / cv ** 2
    t = rng.gamma(k, 100.0 / k, n)
    if delta:
        t = np.ceil(t / delta) * delta
        t = np.round(t, 6)
    else:
        t = np.round(t, 6)
    e = np.ones(n, int)
    if censor_at is not None:
        e[t > censor_at] = 0
        t = np.minimum(t, censor_at)
    return [float(x) for x in t], [int(x) for x in e]


def main():
    sys.path[:0] = [ROOT]
    import numpy as np
    if not hasattr(np, "trapz"):
        np.trapz = np.trapezoid
    from srbench import npcompat  # noqa: F401
    est = dev3_estimator()
    rows = []
    for tag, n, cv, delta, cens, seed in SPECS:
        ages, events = cohort(n, cv, delta, cens, seed)
        t, e = np.asarray(ages, float), np.asarray(events, int)
        out = dict(tag=tag, n=n, target_cv=cv, delta=delta, censor_at=cens, seed=seed, ages=ages, events=events)
        for x in (False, True):
            L, kw, ceiling, floor = est._grid(t, e, delta, dt_rule=x, **GRID_KW)
            out[f"dt_rule_{x}"] = dict(L=L, kw=kw, ceiling=ceiling, floor=floor)
        out["km_cv"] = out["dt_rule_False"]["floor"]["grid_rule"]["cv"]
        rows.append(out)
        print(f"{tag:26s} n={n:5d} cv={out['km_cv']:.5f} dt off={out['dt_rule_False']['kw']['dt']:.3g} "
              f"dev3 rule={out['dt_rule_True']['kw']['dt']:.3g} N={out['dt_rule_False']['kw']['N']}", flush=True)
    om, om_sha = dev3_module("observation_model.py", "dev3_fixture.observation_model")
    wrows = []
    for tag, n, cv, delta, window, seed in WINDOWED:
        ages, events = windowed_cohort(n, cv, delta, window, seed)
        out = dict(tag=tag, n_drawn=n, target_cv=cv, delta=delta, window=list(window), seed=seed, ages=ages,
                   events=events, views={})
        for view in ("J", "H"):
            prep = om.prepare(ages, events, delta, window, window_on=(view == "H"), relabel_on=True)
            t, e = np.asarray(prep.ages, float), np.asarray(prep.events, int)
            v = dict(prep_ages=[float(x) for x in t], prep_events=[int(x) for x in e],
                     window_eff=(None if prep.window_eff is None else [float(x) for x in prep.window_eff]))
            for x in (False, True):
                L, kw, ceiling, floor = est._grid(t, e, delta, dt_rule=x, **GRID_KW)
                v[f"dt_rule_{x}"] = dict(L=L, kw=kw, ceiling=ceiling, floor=floor)
            v["km_cv"] = v["dt_rule_False"]["floor"]["grid_rule"]["cv"]
            out["views"][view] = v
            print(f"{tag:20s} {view} n={t.size:5d} cv={v['km_cv']:.5f} dt off={v['dt_rule_False']['kw']['dt']:.3g} "
                  f"dev3 rule={v['dt_rule_True']['kw']['dt']:.3g} window_eff={v['window_eff']}", flush=True)
        wrows.append(out)
    doc = dict(made_by="make_dev3_grids.py", dev3_commit=DEV3_COMMIT, dev3_estimator_sha256=DEV3_EST_SHA256,
               dev3_observation_model_sha256=om_sha, grid_kw=GRID_KW, cohorts=rows, windowed=wrows)
    with open(os.path.join(HERE, "dev3_grids.json"), "w") as fh:
        json.dump(doc, fh, sort_keys=True, separators=(",", ":"))
        fh.write("\n")


if __name__ == "__main__":
    main()
